const allHits = [];
for (const item of $input.all()) {
  const htmlStr = item.json?.solution?.response || "";
  const match = htmlStr.match(/<body[^>]*>(.*?)<\/body>/is);
  let rawJson = match ? match[1] : htmlStr;

  try {
      rawJson = rawJson.replace(/<[^>]*>?/gm, '');
      const parsed = JSON.parse(rawJson);
      const hits = parsed.hits || [];
      allHits.push(...hits);
  } catch (e) {
      console.log("Error parsing FlareSolverr response:", e);
  }
}
return allHits.map(hit => ({ json: hit }));

// Normaliza + sanitiza titulos. Sale con externalId, licenseType mapeado, imageUrl, tags, sourceUrl.
const LICENSE_MAP = {
  'BY': 'CC-BY', 'BY-SA': 'CC-BY-SA', 'BY-NC': 'CC-BY-NC', 'BY-NC-SA': 'CC-BY-NC',
  'BY-ND': 'CC-BY', 'BY-NC-ND': 'CC-BY-NC', 'CC0': 'CC0',
  'Standard Digital File License': 'commercial',
};
const PATTERNS = [
  /\|?\s*(no |sin )?(ams|supports?|soportes?)\b/gi,
  /\|?\s*easy\s*(to\s*)?print(ing)?\b/gi,
  /\|?\s*no\s*supports?\b/gi,
  /\|?\s*免支撑\S*/g,
  /\|?\s*多色一盘\S*/g,
  /\|?\s*参数优化\S*/g,
  /\|?\s*模型优化\S*/g,
  /\|?\s*\d+\.?\d*mm\s*layer\b.*$/i,
  /\|?\s*\d+\s*walls?\b.*$/i,
  /\|?\s*\d+%\s*infill\b.*$/i,
];
function cleanTitle(t) {
  if (!t) return 'Sin titulo';
  let out = String(t);
  for (const p of PATTERNS) out = out.replace(p, '');
  out = out.replace(/\s*[|·—-—]\s*$/g, '').replace(/\s{2,}/g, ' ').trim();
  return out.length >= 3 ? out : 'Sin titulo';
}
return $input.all().map(({ json: d }) => {
  const rawLicense = (d.license || '').trim();
  const licenseType = LICENSE_MAP[rawLicense] || 'unknown';
  const author = d.designCreator?.name || 'Unknown';
  const externalId = String(d.id ?? '');
  const slug = d.slug || externalId;
  return {
    json: {
      externalId,
      source: 'MAKERWORLD',
      sourceUrl: `https://makerworld.com/en/models/${slug}`,
      title: cleanTitle(d.titleTranslated || d.title),
      description: '',
      imageUrl: d.cover || d.coverPortrait || null,
      licenseType,
      licenseAttribution: `${author} — via MakerWorld`,
      category: (Array.isArray(d.tags) && d.tags[0]) || null,
      tags: Array.isArray(d.tags) ? d.tags.slice(0, 15) : [],
      trendScore: Math.round(d.hotScore ?? d.likeCount ?? 0),
      provider: 'LOCAL',
    },
  };
});

// Suma TODOS los plates de cada instance → variante. Sanitiza nombre de variante. priceFrom = min.
const FILAMENT_PRICE_PER_KG = 400, WASTE_PCT = 5, KWH_PRICE = 4.5, WATTS = 100, MARGIN_PCT = 300;
const VARIANT_PATTERNS = [
  /\|?\s*(no |sin )?(ams|supports?|soportes?)\b/gi,
  /\|?\s*\d+\.?\d*mm\s*layer\b.*$/i,
  /\|?\s*\d+\s*walls?\b.*$/i,
  /\|?\s*\d+%\s*infill\b.*$/i,
  /\|?\s*免支撑\S*/g,
  /\|?\s*多色一盘\S*/g,
  /\|?\s*参数优化\S*/g,
  /\|?\s*模型优化\S*/g,
];
function cleanVariantName(t, idx) {
  if (!t) return `Variante ${idx + 1}`;
  let out = String(t);
  for (const p of VARIANT_PATTERNS) out = out.replace(p, '');
  out = out.replace(/\s*[|·—–-]\s*$/g, '').replace(/\s{2,}/g, ' ').trim();
  return out.length >= 3 ? out : `Variante ${idx + 1}`;
}
function priceForPlates(plates) {
  const grams = plates.reduce((s, p) => s + (Number(p.weight) || 0), 0);
  const seconds = plates.reduce((s, p) => s + (Number(p.prediction) || 0), 0);
  const hours = seconds / 3600;
  if (grams <= 0 || hours <= 0) return null;
  const effectiveGrams = grams * (1 + WASTE_PCT / 100);
  const filament = (effectiveGrams / 1000) * FILAMENT_PRICE_PER_KG;
  const electricity = hours * (WATTS / 1000) * KWH_PRICE;
  const subtotal = filament + electricity;
  return { grams, hours: Number(hours.toFixed(2)), price: Math.round(subtotal * (1 + MARGIN_PCT / 100)) };
}
return $input.all().map((item) => {
  const htmlStr = item.json?.solution?.response || "";
  const match = htmlStr.match(/<body[^>]*>(.*?)<\/body>/is);
  let rawJson = match ? match[1] : htmlStr;
  rawJson = rawJson.replace(/<[^>]*>?/gm, '');

  let json = {};
  try { json = JSON.parse(rawJson); } catch (e) {}

  const instances = json?.instances || [];
  const designExtension = json?.designExtension || {};
  const designPics = Array.isArray(designExtension?.design_pictures) ? designExtension.design_pictures.map(p => p.url).filter(Boolean) : [];
  const cover = json?.cover;
  let images = cover ? [cover, ...designPics.filter(u => u !== cover)] : designPics;


  const variantsRaw = instances.map((ins, i) => {
    const plates = (((ins.extention) || {}).modelInfo || {}).plates || [];
    const calc = priceForPlates(plates);
    if (!calc) return null;
    const insImg = (ins.extention && ins.extention.modelInfo && ins.extention.modelInfo.image) || ins.image || ins.cover || ins.picture;
    return { name: cleanVariantName(ins.title || ins.titleTranslated, i), grams: calc.grams, hours: calc.hours, price: calc.price, imageUrl: insImg };
  }).filter(Boolean);

  variantsRaw.forEach(v => {
    if (v.imageUrl && !images.includes(v.imageUrl)) {
        images.push(v.imageUrl);
    }
  });

  const variants = variantsRaw.sort((a, b) => a.price - b.price);
  const priceFrom = variants.length ? variants[0].price : null;
  const description = (json?.summaryTranslated || json?.summary || '').slice(0, 2000);

  return {
    json: {
      __detail: {
        id: json?.id,
        images,
        description,
        variants,
        priceFrom,
      },
    },
  };
});

const normalized = $('Drop unknown licenses').all();
const stripHtml = (html) => String(html || '').replace(/<[^>]+>/g, ' ').replace(/\s{2,}/g, ' ').trim().slice(0, 2000);

const products = [];
for (const item of items) {
    const det = item?.json?.__detail;
    if (!det || !det.id) continue;

    // Cruce seguro por ID en vez de por indice
    const nItem = normalized.find(x => String(x.json.externalId) === String(det.id));
    if (!nItem) continue;

    const n = nItem.json;
    products.push({
        ...n,
        description: stripHtml(det.description),
        descriptionHtml: det.description || '',
        images: det.images || [],
        variants: det.variants || [],
        priceFrom: det.priceFrom ?? null,
        price: det.priceFrom ?? null,
    });
}

const chunks = [];
const BATCH_SIZE = 15;
for (let i = 0; i < products.length; i += BATCH_SIZE) {
    chunks.push({ json: { products: products.slice(i, i + BATCH_SIZE) } });
}
return chunks;

const GEMINI_API_KEY = $env.GEMINI_API_KEY || "TU_API_KEY_AQUI";
const GEMINI_URL = `https://generativelanguage.googleapis.com/v1beta/models/gemini-flash-latest:generateContent?key=${GEMINI_API_KEY.trim()}`;
const flareUserAgent = "Mozilla/5.0 (Windows NT 10.0; Win64; x64)";

let products = [];
// Si viene envuelto en un chunk { products: [...] } (n8n antiguo o estructurado así)
if (items[0].json && Array.isArray(items[0].json.products) && items[0].json.products.length > 0) {
    products = items[0].json.products;
} 
// Si n8n aplanó el array y recibimos los productos directamente
else if (items[0].json && items[0].json.title !== undefined) {
    products = items.map(i => i.json);
}
else {
    return [{ json: { products: [], DEBUG: "NO SE ENCONTRARON PRODUCTOS EN EL INPUT", inputRecibido: items[0].json } }];
}

let cookieString = "";
try {
    const cookies = $("MakerWorld: search").first().json.solution.cookies || [];
    cookieString = cookies.map(c => `${c.name}=${c.value}`).join("; ");
} catch(e) {}

for (let i = 0; i < products.length; i++) {
    const p = products[i];
    if (!p.title) continue;
    if (GEMINI_API_KEY.includes("TU_API_KEY_AQUI") || GEMINI_API_KEY.trim() === "") {
        p.description = "ERROR: OLVIDASTE PONER TU API KEY DE GEMINI EN EL NODO DE CODIGO!";
        continue;
    }

    // Mapeo de todas las imgenes disponibles para Mercado Libre
    let base64Images = []; // Para enviar a Gemini
    p.meli_pictures = []; // Para Mercado Libre

    try {
        const imgUrls = p.images && p.images.length > 0 ? p.images : (p.imageUrl ? [p.imageUrl] : []);

        for (let idx = 0; idx < Math.min(imgUrls.length, 3); idx++) { // Max 3 imagenes para Gemini
            const imgUrl = imgUrls[idx];
            if (!imgUrl) continue;
            p.meli_pictures.push({ source: imgUrl }); // Para el Payload de Meli

            const imgBuffer = await this.helpers.httpRequest({
                method: 'GET',
                url: imgUrl,
                encoding: null,
                responseType: 'arraybuffer',
                timeout: 5000,
                headers: {
                    'User-Agent': flareUserAgent,
                    'Accept': 'image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8',
                    'Sec-Fetch-Dest': 'image',
                    'Sec-Fetch-Mode': 'no-cors',
                    'Sec-Fetch-Site': 'cross-site',
                    'Referer': 'https://makerworld.com/',
                    'Cookie': cookieString
                }
            });
            if (imgBuffer && imgBuffer.length > 500) {
                let mimeType = null;
                const header = imgBuffer.slice(0, 4).toString("hex").toUpperCase();
                if (header.startsWith("89504E47")) mimeType = "image/png";
                else if (header.startsWith("52494646")) mimeType = "image/webp";
                else if (header.startsWith("FFD8FF")) mimeType = "image/jpeg";

                if (mimeType) {
                    base64Images.push({
                        mimeType: mimeType,
                        data: Buffer.from(imgBuffer).toString("base64")
                    });
                }
            }
        }
    } catch (imgErr) {
        console.log("Error descargando imagen para Gemini:", imgErr.message);
    }

    await new Promise(r => setTimeout(r, 2000));

    // Si no hay variantes, creamos una default
    if (!p.variants || p.variants.length === 0) {
        p.variants = [{ name: "Estandar", grams: 50, price: 100 }];
    }

    const variantsInfo = p.variants.map((v, i) => `[${i+1}] ${v.name} (${v.grams}g, $${v.price})`).join(', ');

    const prompt = `Analiza el siguiente producto para publicarlo en una tienda e-commerce de decoracion y accesorios:
Ttulo Original: ${p.title}
Descripcin original: ${p.description?.slice(0, 500)}
Variantes Fisicas Disponibles (nombre, peso, precio): ${variantsInfo}

REGLA CRITICA DE NEGOCIO:
Tu eres una tienda online que vende el producto FISICO final. El cliente es un comprador normal (no sabe de 3D).
ESTRICTAMENTE PROHIBIDO usar palabras como "impresion 3D", "sin soportes", "STL", "filamento", "maker", "pla".
Describe el beneficio practico, visual o funcional.

Devuelve un JSON valido con esta estructura exacta:
{
  "title": "Nuevo titulo altamente comercial, corto y atractivo",
  "description": "Una descripcion enfocada en los beneficios y usos del producto fisico (max 150 chars).",
  "category": "Categoria comercial general (ej. Hogar, Accesorios, Decoracion)",
  "hashtags": ["tag1", "tag2"],
  "variants": [
    {
       "name": "Nombre comercial de la variante (ej. Premium, Grande, Basico. NO USAR terminos 3D)",
       "price": (el mismo precio original que recibiste de la variante)
    }
  ]
}
Nota para variants: El array de variants debe tener exactamente la misma longitud que las Variantes Fisicas Disponibles que te di, en el mismo orden.
`;

    const parts = [{ text: prompt }];
    for(let img of base64Images) {
        parts.push({
            inlineData: { mimeType: img.mimeType, data: img.data }
        });
    }

    try {
        let response = null;
        let lastError = null;
        for (let attempt = 1; attempt <= 3; attempt++) {
            try {
                response = await this.helpers.httpRequest({
                    method: 'POST',
                    url: GEMINI_URL,
                    headers: { 'Content-Type': 'application/json' },
                    body: { contents: [{ parts }] }
                });
                break;
            } catch (err) {
                lastError = err;
                if (attempt < 3) await new Promise(r => setTimeout(r, 4000));
            }
        }
        if (!response) throw lastError;

        const rawText = response?.candidates?.[0]?.content?.parts?.[0]?.text || "";
        try {
            const jsonMatch = rawText.match(/\{.*\}/s);
            if (jsonMatch) {
                const aiData = JSON.parse(jsonMatch[0]);
                if (aiData.title) p.title = aiData.title;
                if (aiData.description) p.description = aiData.description;
                if (aiData.category) p.category = aiData.category;
                if (aiData.hashtags) p.tags = aiData.hashtags;

                if (aiData.variants && Array.isArray(aiData.variants) && p.variants.length === aiData.variants.length) {
                    p.meli_variations = [];
                    for (let j = 0; j < p.variants.length; j++) {
                        p.variants[j].name = aiData.variants[j].name;
                        p.meli_variations.push({
                            attribute_combinations: [
                                { id: "TAMA\u00D1O", name: "Tama\u00F1o", value_name: aiData.variants[j].name }
                            ],
                            price: p.variants[j].price,
                            available_quantity: 5,
                            picture_ids: [ p.meli_pictures[0]?.source || "" ]
                        });
                    }
                } else {
                     p.meli_variations = [{
                            attribute_combinations: [
                                { id: "TAMA\u00D1O", name: "Tama\u00F1o", value_name: "Est\u00E1ndar" }
                            ],
                            price: p.variants[0].price,
                            available_quantity: 5,
                            picture_ids: [ p.meli_pictures[0]?.source || "" ]
                        }];
                }
            } else {
                p.description = "DEBUG GEMINI (NO JSON)";
            }
        } catch (parseErr) {
            p.description = "DEBUG GEMINI (JSON INVALIDO)";
        }
    } catch (e) {
        let errStr = e.message || e.toString();
        try {
            if (e.response && e.response.data) errStr += " | Data: " + JSON.stringify(e.response.data);
        } catch(dumpErr) {}
        p.description = "DEBUG GEMINI (ERROR CONEXION): " + errStr;
        console.log("Error al llamar a Gemini:", errStr);
    }
}

const finalProducts = products; // Pasamos todo, hasta los errores, para poder ver que pasa
return [{ json: { products: finalProducts, __DEBUG__: { inputLength: items[0].json?.products?.length || "no products arr", initialProductsLength: products.length, firstProduct: products[0] || "none" } } }];

// En lugar de leer el input (que ahora es la respuesta del POST a la base de datos), 
// leemos directamente la salida del nodo Gemini para esta iteracin del loop.
const product = $('Gemini AI Enrich').first().json.products[0];

if (!product) return [];

const payload = {
  title: product.title.substring(0, 60),
  family_name: product.title.substring(0, 60), // MELI max 60 chars
  category_id: "MLM3530", // Categoria generica de adornos/decoracion
  price: product.variants && product.variants.length > 0 ? product.variants[0].price : 100,
  currency_id: "MXN",
  available_quantity: 5,
  buying_mode: "buy_it_now",
  condition: "new",
  listing_type_id: "gold_special",
  pictures: product.meli_pictures || [],
  variations: product.meli_variations || []
};

// Mercado libre no quiere 'variations' si la lista viene vacia.
if (payload.variations.length === 0) {
    delete payload.variations;
}

return [{ json: payload }];
